create extension if not exists pgcrypto;
create type public.property_operation as enum ('Venta','Alquiler');
create type public.property_status as enum ('Disponible','Reservada','Vendida','Alquilada');
create type public.property_type as enum ('Casa','Departamento','PH','Terreno','Local');
create type public.app_role as enum ('admin','agent','editor');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'agent',created_at timestamptz not null default now());
create table public.properties(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,type public.property_type not null,operation public.property_operation not null,status public.property_status not null default 'Disponible',price numeric(14,2) not null check(price>=0),currency text not null check(currency in ('USD','ARS')),city text not null,neighborhood text not null,address text,bedrooms integer not null default 0,bathrooms integer not null default 0,area numeric(10,2) not null check(area>0),parking integer not null default 0,year integer,credit_eligible boolean not null default false,description text not null,features text[] not null default '{}',images text[] not null default '{}',floor_plan text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.leads(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 2 and 120),phone text not null check(length(trim(phone)) between 6 and 40),email text not null check(position('@' in email)>1),subject text not null,message text not null,consent boolean not null check(consent=true),property_id uuid references public.properties(id) on delete set null,created_at timestamptz not null default now(),status text not null default 'new' check(status in ('new','contacted','qualified','closed')));
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id) on delete set null,action text not null,entity text not null,entity_id uuid,payload jsonb,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.properties enable row level security;alter table public.leads enable row level security;alter table public.audit_logs enable row level security;
create policy "public can read available properties" on public.properties for select to anon,authenticated using(status='Disponible');
create policy "staff can manage properties" on public.properties for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','editor'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','editor')));
create policy "users can read own profile" on public.profiles for select to authenticated using(id=auth.uid());
create policy "staff can read leads" on public.leads for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','agent','editor')));
create policy "staff can update leads" on public.leads for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','agent','editor'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','agent','editor')));
create policy "staff can read audit logs" on public.audit_logs for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create index properties_filters_idx on public.properties(operation,type,status,price,bedrooms,city);create index leads_created_idx on public.leads(created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email)); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
